    "linkLabel": null,
    "firm": "Julia Morgan, Architect",
    "styles": [
      "Beaux-Arts",
      "Arts and Crafts"
    ],
    "bio": "Morgan took a civil engineering degree at Berkeley, then besieged the École des Beaux-Arts until it admitted her in 1898 as the first woman in its architecture section — reportedly after examiners had marked her down for being one. Back in California she became the state's first licensed woman architect, and when the 1906 earthquake left her reinforced-concrete Mills College campanile standing amid the rubble, the commissions never stopped: over 700 buildings in a five-decade practice, including a long run of YWCAs, women's clubs and campus buildings for clients other architects didn't court. William Randolph Hearst kept her occupied for nearly thirty years at San Simeon, where she managed everything from Roman pools to the zoo's bear grottos while running her San Francisco office by overnight train. She gave no interviews, published nothing, and burned most of her papers, believing buildings should speak for themselves. The AIA finally awarded her its Gold Medal in 2014, its first to a woman, fifty-seven years after her death.",
    "projects": [
      {
        "title": "Hearst Castle",
        "year": "1919–47",
        "location": "San Simeon, US",
        "blurb": "La Cuesta Encantada: a Mediterranean hilltop compound assembled over decades around Hearst's insatiable collecting, Roman and Neptune pools included.",
        "image": "assets/img/julia-morgan--hearst-castle.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Hearst_Castle"
      },
      {
        "title": "Asilomar Conference Grounds",
        "year": "1913–29",
        "location": "Pacific Grove, US",
        "blurb": "A YWCA retreat of redwood and stone Arts and Crafts lodges among the Monterey dunes; sixteen Morgan buildings survive.",
        "image": "assets/img/julia-morgan--asilomar-conference-grounds.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Asilomar_Conference_Grounds"
      },
      {
        "title": "Berkeley City Club",
        "year": "1930",
        "location": "Berkeley, US",
        "blurb": "A six-story Moorish-Gothic women's club in reinforced concrete, its vaulted indoor pool nicknamed the little castle's crown jewel by members.",
        "image": "assets/img/julia-morgan--berkeley-city-club.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Berkeley_City_Club"
      },
      {
        "title": "El Campanil, Mills College",
        "year": "1904",
        "location": "Oakland, US",
        "blurb": "A 72-foot reinforced-concrete bell tower that rode out the 1906 earthquake untouched and made her reputation.",
        "image": "assets/img/julia-morgan--el-campanil-mills-college.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Mills_College"
      },
      {
        "title": "Chapel of the Chimes",
        "year": "1928",
        "location": "Oakland, US",
        "blurb": "A columbarium of cloistered courts, fountains and filtered light — one of the least morbid buildings for the dead in America.",
        "image": "assets/img/julia-morgan--chapel-of-the-chimes.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Chapel_of_the_Chimes_(Oakland,_California)"
      },
      {
        "title": "Herald Examiner Building",
        "year": "1915",
        "location": "Los Angeles, US",
        "blurb": "Mission Revival headquarters for Hearst's Los Angeles paper, her first big commission for him.",
        "image": null
      },
      {
        "title": "Wyntoon",
        "year": "1933–43",
        "location": "McCloud River, US",
        "blurb": "Hearst's forest estate rebuilt as a Bavarian fairy-tale village on the McCloud, murals and all.",
        "image": "assets/img/julia-morgan--wyntoon.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Wyntoon"
      },
      {
        "title": "St. John's Presbyterian Church",
        "year": "1910",
        "location": "Berkeley, US",
        "blurb": "Exposed redwood framing as the whole architecture; a Bay Region landmark now serving as a playhouse.",
        "image": "assets/img/julia-morgan--st-john-s-presbyterian-church.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/St._John's_Presbyterian_Church_(Berkeley,_California)"
      },
      {
        "title": "Fairmont Hotel Restoration",
        "year": "1907",
        "location": "San Francisco, US",
        "blurb": "The fire-gutted hotel reopened exactly one year after the earthquake, with Morgan the engineer-architect who made it stand.",
        "image": "assets/img/julia-morgan--fairmont-hotel-restoration.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Fairmont_San_Francisco"
      },
      {
        "title": "Hearst Memorial Gymnasium",
        "year": "1927",
        "location": "Berkeley, US",
        "blurb": "A Beaux-Arts women's gymnasium for the Berkeley campus, designed with Bernard Maybeck, pools framed by urns.",
        "image": "assets/img/julia-morgan--hearst-memorial-gymnasium.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Hearst_Memorial_Gymnasium"
      }
    ],
    "portrait": "assets/img/julia-morgan--portrait.jpg",
