        "year": "1990",
        "location": "Hong Kong, HK",
        "blurb": "A tower of diagonally braced glass prisms growing like bamboo — Hong Kong's skyline sharpened to a point.",
        "image": "assets/img/im-pei--bank-of-china-tower.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Bank_of_China_Tower_(Hong_Kong)"
