        "year": "1978",
        "location": "Santa Monica, US",
        "blurb": "A pink Dutch colonial bungalow wrapped in chain-link, plywood and corrugated metal — the cheap-materials manifesto that started everything.",
        "image": "assets/img/frank-gehry--gehry-residence.jpg",
        "wikiUrl": "https://en.wikipedia.org/wiki/Gehry_Residence"
